def seed_breeds():
    create_db_and_tables()

    with Session(engine) as session:
        for breed_data in breeds:
            existing = session.exec(
                select(Breed).where(Breed.name == breed_data["name"])
            ).first()

            if not existing:
                session.add(Breed(**breed_data))

        session.commit()
        print("Breeds seeded successfully.")

if __name__ == "__main__":
    seed_breeds()